                .setLengthData(GenericParticleData.create(0.75f))
                .setTransparencyData(transparencyData)
                .setColorData(colorData.getColor())
                .enableForcedSpawn()
                .setLifetime(30)
                .enableNoClip();
        for (int i = 0; i < duration; i++) {
            builder.setLifeDelay(delay + i)
                    .clearSpawnActors()
                    .addSpawnActor(p -> {
                        float offsetScale = 0.2f;
                        Vec3 offset = new Vec3(
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale),
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale),
                                Easing.SINE_IN_OUT.asWeighedRandom(random, -offsetScale, offsetScale)
                        );
                        var position = target.position().add(0, target.getBbHeight() / 2, 0).add(offset);
                        p.setParticlePosition(position);
                        p.setParticleSpeed(target.getDeltaMovement().scale(0.3f));
                    })
                    .spawn(level, pos);
        }
    }

@Override
	public void tick() {
		if (this.shouldRemove) {
			if (this.age >= this.lifetime) {
				this.remove();
			}
		} else {
			if (!this.canContinue()) {
				this.shouldRemove = true;
				this.lifetime = this.age + this.trailInfo.trailLifetime();
			}
		}

		this.age++;
		this.trailEdges.removeIf(v -> !v.isAlive());

		if (!this.canCreateNextCurve()) {
			return;
		}

		Vec3 lastPos = this.owner.getOriginal().getPosition(0.0F);
		double xd = Math.pow(this.owner.getOriginal().getX() - lastPos.x, 2);
		double yd = Math.pow(this.owner.getOriginal().getY() - lastPos.y, 2);
		double zd = Math.pow(this.owner.getOriginal().getZ() - lastPos.z, 2);
		float move = (float)Math.sqrt(xd + yd + zd) * 2.0F;

		this.setSize(this.bbWidth + move, this.bbHeight + move);
		this.createNextCurve();
	}

public static LayerDefinition createArmorLayer(CubeDeformation deformation) {
        MeshDefinition meshdefinition = HumanoidModel.createMesh(deformation, 0.0F);
        PartDefinition partdefinition = meshdefinition.getRoot();
        PartDefinition leftLeg = partdefinition.getChild("left_leg");
        PartDefinition rightLeg = partdefinition.getChild("right_leg");

        CubeDeformation deformationPants = deformation.extend(0.1F);

        rightLeg.addOrReplaceChild("right_pants", CubeListBuilder.create().texOffs(0, 32).addBox(-2.0F, 0.0F, -2.0F, 4.0F, 12.0F, 4.0F, deformationPants), PartPose.offset(0.0F, 0.0F, 0.0F));

        leftLeg.addOrReplaceChild("left_pants", CubeListBuilder.create().texOffs(0, 48).addBox(-2.0F, 0.0F, -2.0F, 4.0F, 12.0F, 4.0F, deformationPants), PartPose.offset(0.0F, 0.0F, 0.0F));

        return LayerDefinition.create(meshdefinition, 128, 128);
    }

